S = "Hakeem Force Academy"
QS = [
(S, "If the 4th day of a month is Tuesday, what day is the 15th of that month?", ["Friday", "Saturday", "Sunday", "Monday"], 1,
 "From the 4th to the 15th is 11 days. 11 = 7 + 4, so the day is 4 days after Tuesday, which is Saturday.",
 "Counting the difference in dates and taking the remainder after dividing by 7 solves every such day question.", [882]),
(S, "Which is the longest railway tunnel in Pakistan?", ["Khojak Tunnel", "Lowari Tunnel", "Kohat Tunnel", "Malakand Tunnel"], 0,
 "The Khojak Tunnel, built in 1891 in the Khojak Pass of Balochistan on the Quetta-Chaman line, is about 3.9 km long and is Pakistan's longest railway tunnel.",
 "The Lowari Tunnel in Khyber Pakhtunkhwa is longer, but it is a road tunnel, not a railway tunnel.", [2545, 4616, 4626, 40]),
(S, "What is the capital of Turkey?", ["Istanbul", "Ankara", "Izmir", "Bursa"], 1,
 "Ankara is the capital of Turkey, chosen by Ataturk in 1923 when the republic was founded.",
 "Istanbul is the largest city of Turkey but not its capital.", [282]),
(S, "Ali's present age is 3 years and his sister is twice his age. What will be the age of his sister when Ali is 8 years old?", ["13", "16", "10", "11"], 3,
 "Sister's age now is 2 x 3 = 6, so she is 3 years older than Ali. When Ali is 8, she is 8 + 3 = 11.",
 "The age difference between two people always stays the same.", [1750]),
(S, "Salman is 4 years old and Ali is twice the age of Salman. When Salman is 12 years old, what will be the age of Ali?", ["24", "16", "20", "18"], 1,
 "Ali is 2 x 4 = 8 now, so he is 4 years older than Salman. When Salman is 12, Ali is 12 + 4 = 16.",
 "Do not double the later age; only the present ages are in the ratio 2 to 1.", [2979]),
(S, "Umar's age is 4 years and his sister is three times his age. What will be the sister's age when Umar is 11 years old?", ["33", "19", "12", "15"], 1,
 "Sister is 3 x 4 = 12 now, so she is 8 years older than Umar. When Umar is 11, she is 11 + 8 = 19.",
 "After 7 years both ages increase by 7, so 12 + 7 = 19.", [890]),
(S, "9/2 is what type of number?", ["Integer", "Rational number", "Irrational number", "Natural number"], 1,
 "9/2 is a ratio of two integers with a non-zero denominator, so it is a rational number (4.5), an improper fraction.",
 "Every integer is also rational, but 9/2 is not an integer.", [1606]),
(S, "What type of constitution was the 1956 Constitution of Pakistan?", ["Presidential", "Parliamentary", "Unitary monarchy", "Military"], 1,
 "The 1956 Constitution, Pakistan's first, set up a federal parliamentary republic with a unicameral National Assembly.",
 "It was abrogated in October 1958 when martial law was imposed.", [4082]),
(S, "Beauty is to ugliness as adversity is to what?", ["Prosperity", "Hardship", "Misfortune", "Difficulty"], 0,
 "Ugliness is the opposite of beauty, and the opposite of adversity (hardship) is prosperity.",
 "Hardship, misfortune and difficulty are synonyms of adversity, not opposites.", [1819]),
(S, "Beauty is to ugliness as diversity is to what?", ["Variety", "Uniformity", "Difference", "Range"], 1,
 "Ugliness is the opposite of beauty, and the opposite of diversity (variety) is uniformity.",
 "Variety, difference and range are close in meaning to diversity.", [1820]),
(S, "Who is the President of Ukraine?", ["Petro Poroshenko", "Volodymyr Zelensky", "Viktor Yanukovych", "Leonid Kuchma"], 1,
 "Volodymyr Zelensky has been President of Ukraine since May 2019 and still holds the office in 2026.",
 "Petro Poroshenko was his predecessor, from 2014 to 2019.", [93]),
(S, "Who is the current Prime Minister of Ukraine?", ["Serhii Koretskyi", "Denys Shmyhal", "Yulia Svyrydenko", "Volodymyr Groysman"], 0,
 "Serhii Koretskyi, formerly head of Naftogaz, was confirmed as Prime Minister by the Verkhovna Rada on 16 July 2026.",
 "Yulia Svyrydenko served as Prime Minister from July 2025 before him, and Denys Shmyhal before her.", [1417]),
(S, "Who was the first President of Ukraine?", ["Leonid Kravchuk", "Leonid Kuchma", "Viktor Yushchenko", "Petro Poroshenko"], 0,
 "Leonid Kravchuk became the first President of independent Ukraine in December 1991 after the Soviet Union broke up.",
 "He served until 1994, when Leonid Kuchma succeeded him.", [1465]),
(S, "Bakar is older than Ali and Umair is younger than Ali. Which statement is correct?", ["Umair is the oldest", "Ali is the oldest", "Bakar is the oldest", "Ali is the youngest"], 2,
 "Bakar is older than Ali, and Ali is older than Umair, so the order is Bakar, Ali, Umair. Bakar is the oldest and Umair the youngest.",
 "Such questions are solved by arranging the names in a line from oldest to youngest.", [783]),
(S, "Which daughter of Hazrat Umar (RA) was married to the Holy Prophet (PBUH)?", ["Hazrat Hafsa (RA)", "Hazrat Ayesha (RA)", "Hazrat Zainab (RA)", "Hazrat Sauda (RA)"], 0,
 "Hazrat Hafsa bint Umar (RA) married the Holy Prophet (PBUH) in 3 AH and is one of the Mothers of the Believers.",
 "She was earlier the widow of Khunais bin Hudhafa (RA), and the first copy of the Quran was kept with her.", [4567]),
(S, "In which Hijri year did the Holy Prophet (PBUH) perform the first Umrah that was completed at Makkah (Umrat-ul-Qaza)?", ["6 AH", "7 AH", "8 AH", "10 AH"], 1,
 "In 6 AH the Muslims were stopped at Hudaybiyyah and returned. In 7 AH, under the treaty, the Prophet performed the Umrah in Makkah (Umrat-ul-Qaza).",
 "Sources count the Hudaybiyyah journey of 6 AH as an Umrah too, so wording differs between books.", [2608, 975]),
(S, "Which uncle of the Holy Prophet (PBUH), known for his enmity to him, is cursed in the Quran?", ["Abu Talib", "Hazrat Abbas", "Abu Lahab", "Hazrat Hamza"], 2,
 "Surah Al-Masad (Al-Lahab) condemns Abu Lahab, the Prophet's uncle, for his hostility to Islam.",
 "Abu Lahab is the only enemy of the Prophet named in the Quran, and his wife is also mentioned in that surah.", [669, 5402]),
(S, "Which uncle of the Holy Prophet (PBUH) was martyred in the Battle of Uhud?", ["Hazrat Abbas (RA)", "Hazrat Hamza (RA)", "Abu Talib", "Hazrat Zubair (RA)"], 1,
 "Hazrat Hamza (RA), called Asadullah (Lion of Allah), was killed by Wahshi in the Battle of Uhud in 3 AH.",
 "He is also known as Sayyid-ush-Shuhada, the chief of the martyrs.", [1374]),
(S, "What is a matrix whose number of rows is not equal to its number of columns called?", ["Square matrix", "Rectangular matrix", "Identity matrix", "Diagonal matrix"], 1,
 "A matrix with unequal numbers of rows and columns (m x n with m not equal to n) is a rectangular matrix.",
 "If rows and columns are equal, it is a square matrix.", [3319, 3321]),
(S, "For the unit vector i, what is the value of the dot product i . i?", ["0", "1", "i", "-1"], 1,
 "The dot product of a vector with itself is the square of its magnitude. The magnitude of i is 1, so i . i = 1.",
 "For different unit vectors, such as i . j, the dot product is 0.", [1205]),
(S, "What is the value of the logarithm of unity (log 1)?", ["1", "0", "10", "Undefined"], 1,
 "For any valid base b, b raised to the power 0 equals 1, so log 1 = 0.",
 "The logarithm of the base itself is always 1.", [1134]),
(S, "In which city is the International Islamic University (IIUI) located?", ["Lahore", "Karachi", "Islamabad", "Peshawar"], 2,
 "The International Islamic University is in Islamabad, the capital of Pakistan.",
 "It was established in 1980 and given its present status in 1985.", [4372, 4373]),
(S, "Unscramble the word SAPIR. Is it the name of a bird, a country or a city?", ["A bird", "A country", "A city", "A river"], 2,
 "The letters of SAPIR form PARIS, which is a city, the capital of France.",
 "Paris stands on the River Seine.", [3133]),
(S, "In which province does the Upper Indus Plain mainly lie?", ["Sindh", "Punjab", "Balochistan", "Khyber Pakhtunkhwa"], 1,
 "The Upper Indus Plain, north of Mithankot, covers most of Punjab, where the five rivers join the Indus.",
 "The Lower Indus Plain to the south lies mainly in Sindh.", [2651, 2652, 537]),
(S, "In which year was Urdu declared the national language of Pakistan, as commonly taught?", ["1947", "1948", "1956", "1973"], 1,
 "Quaid-e-Azam declared Urdu the state language at Dhaka in March 1948, and this is the usual textbook answer.",
 "The 1973 Constitution also names Urdu as the national language of Pakistan.", [542]),
(S, "What is the meaning of the name Pakistan?", ["Land of the Pure", "Land of Five Rivers", "Land of Peace", "Land of Muslims"], 0,
 "Pak means pure and stan means land, so Pakistan means the Land of the Pure.",
 "The name was coined by Choudhry Rahmat Ali in 1933.", [1141]),
(S, "What is the original meaning of the word Urdu?", ["Language", "Camp or army", "Poetry", "Pure"], 1,
 "Urdu comes from the Turkish word ordu, meaning camp or army, as the language grew in the military camps and bazaars.",
 "It is also called Lashkari zaban, the language of the army.", [285]),
]
